<?php
declare(strict_types=1);
namespace Brebo\Office\Finance\Center;
use PDO;
require_once __DIR__.'/Planning.php';
final class Report {
  private Ledger $ledger;
  public function __construct(private readonly PDO $db,private readonly string $actor){$this->ledger=new Ledger($db,$actor);}
  public function salesRows(): array{
    $this->ledger->authorize();$q=$this->db->prepare("SELECT i.id,i.operator_id,i.office_project_id,i.invoice_number,i.invoice_date,i.due_date,i.net_cents,i.gross_cents,i.paid_cents,i.status,i.revision,i.customer_json,COALESCE(x.g_cents,0) AS g_cents FROM office_finance_sales_invoice i LEFT JOIN office_finance_sales_context x ON x.invoice_id=i.id WHERE (i.office_project_id IS NULL AND i.operator_id=?) OR EXISTS (SELECT 1 FROM office_project_memberships m WHERE m.project_id=i.office_project_id AND m.operator_id=? AND m.permission IN ('read','manage')) ORDER BY i.invoice_date DESC,i.id DESC");$q->execute([$this->actor,$this->actor]);return $q->fetchAll(PDO::FETCH_ASSOC);
  }
  public function read(string $today): array{
    $this->ledger->authorize();Amounts::date($today);$year=substr($today,0,4);$postings=$this->ledger->postings();$sales=$this->salesRows();$purchase=$this->ledger->purchaseChoices();$hours=$this->ledger->hoursChoices();$plans=(new Planning($this->db,$this->actor))->plans();
    $basis=['sales'=>array_map(static fn($r)=>[$r['id'],$r['revision'],$r['status']],$sales),'opening'=>(new Planning($this->db,$this->actor))->latestOpening()['id']??null,'postings'=>array_map(static fn($r)=>[$r['id'],$r['revision'],$r['status']],$postings),'purchases'=>array_map(static fn($r)=>[$r['id'],$r['invoice_date'],$r['total']],$purchase),'hours'=>array_map(static fn($r)=>[$r['id'],$r['revision'],$r['reviewed_seconds']],$hours),'plans'=>array_map(static fn($r)=>[$r['id'],$r['status'],$r['paid_cents']],$plans)];
    $q=$this->db->prepare("SELECT id,invoice_date,total FROM office_finance_invoices WHERE status='draft' AND created_by=? ORDER BY id");$q->execute([$this->actor]);$ownDrafts=$q->fetchAll(PDO::FETCH_ASSOC);$basis['own_drafts']=$ownDrafts;
    $hash=Amounts::hash($basis);$pendingPurchases=array_filter($purchase,static fn($r)=>empty($r['invoice_date'])||(substr($r['invoice_date'],0,4)===$year&&$r['invoice_date']<=$today));$pendingHours=array_filter($hours,static function($r)use($year,$today){$d=(new \DateTimeImmutable($r['worked_at'],new \DateTimeZone('UTC')))->setTimezone(new \DateTimeZone('Europe/Amsterdam'))->format('Y-m-d');return substr($d,0,4)===$year&&$d<=$today;});
    $result=['as_of'=>$today,'source_hash'=>$hash,'revenue_cents'=>0,'direct_cents'=>0,'labor_cents'=>0,'overhead_cents'=>0,'gross_margin_cents'=>null,'operating_result_cents'=>null,'cost_review_ready'=>false,'pending_purchase_count'=>count(array_filter($ownDrafts,static fn($v)=>empty($v['invoice_date'])||(substr($v['invoice_date'],0,4)===$year&&$v['invoice_date']<=$today)))+count(array_filter($pendingPurchases,static fn($v)=>!in_array($v['id'],array_column($ownDrafts,'id')))),'unpriced_hours_count'=>count($pendingHours),'postings'=>$postings,'sales'=>$sales,'purchase_choices'=>$purchase,'hours'=>$hours,'plans'=>$plans,'forecast'=>null,'forecast_reasons'=>[]];
    foreach($sales as $i)if(($i['invoice_number']??'')!==''&&in_array($i['status'],['sent','reminder_sending','reconciliation_required'],true)&&substr($i['invoice_date'],0,4)===$year&&$i['invoice_date']<=$today)$result['revenue_cents']+=(int)$i['net_cents'];
    foreach($postings as $p)if($p['status']==='booked'&&substr($p['booking_date'],0,4)===$year&&$p['booking_date']<=$today)foreach($p['lines'] as $line)$result[$line['category'].'_cents']+=(int)$line['net_cents'];
    $result['valuation_stale']=false;foreach($postings as $p)if($p['status']==='booked'&&$p['source_kind']==='hours'&&substr($p['booking_date'],0,4)===$year){$q=$this->db->prepare('SELECT revision,approval_status FROM office_onsite_hours_reviews WHERE id=?');$q->execute([$p['source_id']]);$current=$q->fetch(PDO::FETCH_ASSOC);$snapshot=json_decode($p['snapshot_json'],true,64,JSON_THROW_ON_ERROR);if(!$current||$current['approval_status']!=='approved'||(int)$current['revision']!==(int)$snapshot['review']['revision'])$result['valuation_stale']=true;}
    $q=$this->db->prepare('SELECT * FROM office_finance_period_reviews WHERE operator_id=? AND through_date=? ORDER BY id DESC LIMIT 1');$q->execute([$this->actor,$today]);$review=$q->fetch(PDO::FETCH_ASSOC);
    $valid=$review&&hash_equals($review['source_hash'],$hash);$result['review']=$review?:null;
    if(!$result['valuation_stale']&&$valid&&(int)$review['costs_complete']===1&&(int)$review['hours_complete']===1&&(int)$review['overhead_complete']===1&&$result['pending_purchase_count']===0&&count($pendingHours)===0){$result['cost_review_ready']=true;$result['gross_margin_cents']=$result['revenue_cents']-$result['direct_cents']-$result['labor_cents'];$result['operating_result_cents']=$result['gross_margin_cents']-$result['overhead_cents'];}
    if(!$this->ledger->bankAccess())$result['forecast_reasons'][]='Bankinzage vereist voor een liquiditeitsprognose.';
    $opening=(new Planning($this->db,$this->actor))->latestOpening();$result['opening']=$opening;
    if(!$opening)$result['forecast_reasons'][]='Bevestig de beginsaldi van alle gewone rekeningen en G-rekeningen.';
    if(!$valid||(int)($review['cash_complete']??0)!==1)$result['forecast_reasons'][]='Controleer en bevestig de complete betaalplanning.';
    if($opening&&$this->ledger->bankAccess()&&$valid&&(int)$review['cash_complete']===1)$result=$this->forecast($result,$opening,$today);
    return $result;
  }
  public function confirm(array $input,string $today): void{
    $this->ledger->authorize(true);$r=$this->read($today);if(!hash_equals($r['source_hash'],(string)($input['source_hash']??'')))throw new \DomainException('De administratie is gewijzigd; controleer opnieuw.');$flags=[];foreach(['costs','hours','overhead','cash'] as $key)$flags[$key]=($input[$key.'_complete']??'')==='yes'?1:0;
    if(($flags['costs']&&$r['pending_purchase_count']>0)||($flags['hours']&&$r['unpriced_hours_count']>0))throw new \DomainException('Boek eerst de inkoopconcepten en waardeer de goedgekeurde uren in deze periode.');$ref=Amounts::text($input['reference']??null);
    $this->db->beginTransaction();try{$this->db->prepare('INSERT INTO office_finance_period_reviews(operator_id,through_date,costs_complete,hours_complete,overhead_complete,cash_complete,evidence_reference,source_hash,created_at) VALUES(?,?,?,?,?,?,?,?,?)')->execute([$this->actor,$today,$flags['costs'],$flags['hours'],$flags['overhead'],$flags['cash'],$ref,$r['source_hash'],gmdate('c')]);$this->db->prepare('INSERT INTO office_finance_center_audit(operator_id,event,entity_id,detail_json,created_at) VALUES(?,?,?,?,?)')->execute([$this->actor,'period_review_confirmed',null,json_encode(['through_date'=>$today,'source_hash'=>$r['source_hash'],'flags'=>$flags],JSON_THROW_ON_ERROR),gmdate('c')]);$this->db->commit();}catch(\Throwable $e){$this->db->rollBack();throw $e;}
  }
  private function forecast(array $r,array $opening,string $today): array{
    $q=$this->db->query('SELECT id FROM office_finance_sales_invoice');$allSales=$q->fetchAll(PDO::FETCH_COLUMN);
    $q=$this->db->query("SELECT id FROM office_finance_postings WHERE status='booked'");$allCosts=$q->fetchAll(PDO::FETCH_COLUMN);
    $q=$this->db->prepare("SELECT 1 FROM office_finance_cash_plan WHERE operator_id<>? AND status='planned' LIMIT 1");$q->execute([$this->actor]);
    if(array_diff($allSales,array_column($r['sales'],'id'))||array_diff($allCosts,array_column($r['postings'],'id'))||$q->fetchColumn()){$r['forecast_reasons'][]='De zichtbare financiële scope is niet volledig voor een bedrijfsbrede liquiditeitsprognose.';return $r;}
    $balance=['regular'=>0,'g'=>0];foreach($opening['accounts'] as $a)$balance[$a['account_bucket']]+=(int)$a['balance_cents'];$events=[];$knownCash=[];
    $clauses=[];$args=[];
    foreach(['sale'=>$r['sales'],'expense'=>$r['postings'],'plan_in'=>$r['plans'],'plan_out'=>$r['plans']] as $type=>$rows){$ids=array_map(static fn($v)=>(int)$v['id'],$rows);if(!$ids)continue;$clauses[]='(entity_type=? AND entity_id IN ('.implode(',',array_fill(0,count($ids),'?')).'))';$args[]=$type;array_push($args,...$ids);}
    $q=$this->db->prepare('SELECT * FROM office_finance_cash_records WHERE '.($clauses?implode(' OR ',$clauses):'1=0').' ORDER BY payment_date,id');$q->execute($args);$cash=$q->fetchAll(PDO::FETCH_ASSOC);
    foreach($cash as $c){$key=$c['entity_type'].':'.$c['entity_id'];$knownCash[$key]??=['regular'=>0,'g'=>0];$knownCash[$key][$c['account_bucket']]+=(int)$c['amount_cents'];if($c['payment_date']>$opening['balance_date']&&$c['payment_date']<=$today)$balance[$c['account_bucket']]+=(in_array($c['entity_type'],['sale','plan_in'],true)?1:-1)*(int)$c['amount_cents'];}
    foreach($r['sales'] as $i){
      $q=$this->db->prepare("SELECT s.* FROM office_finance_sales_receipt s WHERE s.invoice_id=? AND NOT EXISTS (SELECT 1 FROM office_finance_cash_records c WHERE c.entity_type='sale' AND c.entity_id=s.invoice_id AND c.bank_reference=s.evidence_reference)");$q->execute([$i['id']]);
      foreach($q->fetchAll(PDO::FETCH_ASSOC) as $receipt){if((int)$i['g_cents']>0){$r['forecast_reasons'][]='Bestaande ontvangsten op G-facturen moeten eerst per rekening worden geclassificeerd.';continue;}$key='sale:'.$i['id'];$knownCash[$key]??=['regular'=>0,'g'=>0];$knownCash[$key]['regular']+=(int)$receipt['amount_cents'];if($receipt['receipt_date']>$opening['balance_date']&&$receipt['receipt_date']<=$today)$balance['regular']+=(int)$receipt['amount_cents'];}
    }
    foreach($r['sales'] as $i){if($i['status']==='draft')continue;if(($i['invoice_number']??'')===''||!in_array($i['status'],['sent','reminder_sending'],true)){$r['forecast_reasons'][]='Los onzekere verkoopverzendingen eerst op.';continue;}$open=(int)$i['gross_cents']-(int)$i['paid_cents'];if($open<=0)continue;$recorded=$knownCash['sale:'.$i['id']]??['regular'=>0,'g'=>0];if((int)$i['g_cents']>0&&array_sum($recorded)!==(int)$i['paid_cents']){$r['forecast_reasons'][]='Classificeer bestaande deelontvangsten van G-facturen per rekeningsoort.';continue;}$g=max(0,(int)$i['g_cents']-$recorded['g']);if($g>$open){$r['forecast_reasons'][]='Controleer de betaalverdeling van een verkoopfactuur.';continue;}$events[]=['date'=>max($today,$i['due_date']),'regular'=>$open-$g,'g'=>$g,'source'=>'sale:'.$i['id']];}
    foreach($r['postings'] as $p){if($p['status']!=='booked'||(int)$p['cash_due']!==1)continue;$open=(int)$p['gross_cents']-(int)$p['paid_cents'];if($open<=0)continue;$recorded=$knownCash['expense:'.$p['id']]??['regular'=>0,'g'=>0];$g=max(0,(int)$p['g_cents']-$recorded['g']);if(!$p['due_date']||$g>$open){$r['forecast_reasons'][]='Controleer vervaldatum en G-verdeling van de inkoopboekingen.';continue;}$events[]=['date'=>max($today,$p['due_date']),'regular'=>-($open-$g),'g'=>-$g,'source'=>'expense:'.$p['id']];}
    foreach($r['plans'] as $p)if($p['status']==='planned'&&(int)$p['amount_cents']>(int)$p['paid_cents']){$sign=$p['direction']==='in'?1:-1;$events[]=['date'=>max($today,$p['due_date']),'regular'=>$p['account_bucket']==='regular'?$sign*((int)$p['amount_cents']-(int)$p['paid_cents']):0,'g'=>$p['account_bucket']==='g'?$sign*((int)$p['amount_cents']-(int)$p['paid_cents']):0,'source'=>'plan:'.$p['id']];}
    if($r['forecast_reasons'])return $r;usort($events,static fn($a,$b)=>strcmp($a['date'],$b['date']));$horizons=[];$date=new \DateTimeImmutable($today,new \DateTimeZone('UTC'));
    foreach([30,60,90] as $days){$end=$date->modify('+'.$days.' days')->format('Y-m-d');$b=$balance;$in=['regular'=>0,'g'=>0];$out=$in;foreach($events as $e)if($e['date']<=$end)foreach(['regular','g'] as $bucket){$b[$bucket]+=$e[$bucket];if($e[$bucket]>=0)$in[$bucket]+=$e[$bucket];else $out[$bucket]-=$e[$bucket];}$horizons[$days]=['end_date'=>$end,'opening'=>$balance,'incoming'=>$in,'outgoing'=>$out,'ending'=>$b];}
    $r['forecast']=['as_of'=>$today,'balance_date'=>$opening['balance_date'],'horizons'=>$horizons,'events'=>$events];return $r;
  }
}
